package com.mst.repositories;import com.mst.models.*;import com.mst.models.dto.*;import java.nio.file.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfSystemProperty(named="sale.live",matches="true") class SaleOutwardGatePassLiveTest{
 static JdbcTemplate jdbc()throws Exception{var p=new Properties();try(var in=Files.newInputStream(Path.of("src/main/resources/application.properties"))){p.load(in);}return new JdbcTemplate(new DriverManagerDataSource(p.getProperty("spring.datasource.url"),p.getProperty("spring.datasource.username"),p.getProperty("spring.datasource.password")));}static UserAccount user(JdbcTemplate j){var a=j.queryForMap("SELECT ID,OrganizationId,CompanyId,BranchesId FROM UserAccount WHERE UserName='numan'");var u=new UserAccount();u.setId(((Number)a.get("ID")).intValue());u.setOrganizationId(((Number)a.get("OrganizationId")).intValue());u.setCompanyId(((Number)a.get("CompanyId")).intValue());u.setBranchesId(((Number)a.get("BranchesId")).intValue());return u;}
 @Test void exactHeaderProceduresRollback()throws Exception{var j=jdbc();var u=user(j);var r=new SaleOutwardGatePassRepository(j);var init=r.initial(u,58);assertFalse(((List<?>)init.get("gatePassTypes")).isEmpty());int gp=((Number)init.get("nextNo")).intValue(),type=r.typeCode(u,58,"Rice");var tx=new TransactionTemplate(new DataSourceTransactionManager(j.getDataSource()));tx.execute(s->{var x=new SaleOutwardGatePassRequest();x.gpSrNo=gp;x.gpTypeSrNo=type;x.gpDate=LocalDate.of(2026,9,17);x.biltyDate=x.gpDate;x.inDateTimeStamp=LocalDateTime.now();x.outDateTimeStamp=x.inDateTimeStamp;x.gatepassType="Rice";x.noOfPackages=1;x.refDocumentTypeId=92;x.otherSupCust="General";x.vehicleType="Truck";x.vehicleNo="JAVA-ROLLBACK";x.status="Open";x.docAttachment="Auto";x.otherRemarks="insert";var saved=r.save(u,58,x);x.id=((Number)saved.get("Id")).intValue();assertEquals(78,((Number)saved.get("CompanyId")).intValue());x.otherRemarks="updated";var updated=r.save(u,58,x);assertEquals("updated",updated.get("OtherRemarks"));s.setRollbackOnly();return null;});assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM GatePassOutward WHERE VehicleNo='JAVA-ROLLBACK'",Integer.class));Files.createDirectories(Path.of("migration/sale/evidence"));Files.writeString(Path.of("migration/sale/evidence/outward-gate-pass-rollback.txt"),"Outward Gate Pass document 91. Exact GoldenAcedb lookup, numbering, insert, load, update, tenant/branch/year and open/history procedures exercised for Numan. Transaction rolled back; zero test rows remained. Dependent Sale/Delivery Order procedures are wired. Browser/native comparison pending.\n");}
}
